 if($oPath==='/api/services'&&$oMethod==='GET'){$rows=$pdo->query('SELECT * FROM `services` WHERE `is_active`=1 ORDER BY `sort_order`,`id`')->fetchAll();$oJson(200,array_map($oCamel,$rows));return true;}
 $token=trim((string)($_SERVER['HTTP_X_COMMUNITY_TOKEN']??''));$mid=null;if($token!==''){$s=$pdo->prepare('SELECT `member_id` FROM `community_auth_tokens` WHERE `token_hash`=? AND `expires_at`>? LIMIT 1');$s->execute([hash('sha256',$token),(int)floor(microtime(true)*1000)]);$v=$s->fetchColumn();if($v!==false)$mid=(int)$v;}
