 if($oPath==='/api/service-orders'&&$oMethod==='POST'){$b=json_decode(file_get_contents('php://input')?:'{}',true);$slug=trim((string)($b['serviceSlug']??''));$name=trim((string)($b['serviceName']??''));$customer=trim((string)($b['customerName']??''));$phone=trim((string)($b['customerPhone']??''));if($slug===''||$name===''||$customer===''||$phone===''){$oJson(400,['message'=>'بيانات الطلب ناقصة']);return true;}$now=(int)floor(microtime(true)*1000);$num='ORD-'.strtoupper(base_convert((string)$now,10,36));$s=$pdo->prepare('INSERT INTO `service_orders` (`member_id`,`order_number`,`service_slug`,`service_name`,`service_variant`,`amount`,`customer_name`,`customer_phone`,`customer_email`,`receipt_url`,`payment_method`,`status`,`notes`,`created_at`,`updated_at`) VALUES (?,?,?,?,?,?,?,?,?,?,"bank_transfer","pending",?,?,?)');$s->execute([$mid,$num,$slug,$name,trim((string)($b['serviceVariant']??'')),(int)($b['amount']??0),$customer,$phone,trim((string)($b['customerEmail']??'')),trim((string)($b['receiptUrl']??'')),trim((string)($b['notes']??'')),$now,$now]);$id=(int)$pdo->lastInsertId();$s=$pdo->prepare('SELECT * FROM `service_orders` WHERE `id`=?');$s->execute([$id]);$oJson(201,$oCamel($s->fetch()));return true;}
